private static double calculateTotalAmount(Invoice invoice, Map<String, Play> plays) {
    double totalAmount = 0;
    for (Performance perf : invoice.getPerformances()) {
        Play play = plays.get(perf.getPlayID());
        if (play == null) {
            throw new IllegalArgumentException("Unknown play: " + perf.getPlayID());
        }
        totalAmount += calculateAmountForPerformance(perf, play);
    }
    return totalAmount;
}

private static double calculateAmountForPerformance(Performance perf, Play play) {
    double thisAmount = 0;
    switch (play.getType()) {
        case "tragedy":
            thisAmount = 40000;
            if (perf.getAudience() > 30) {
                thisAmount += 1000 * (perf.getAudience() - 30);
            }
            break;

        case "comedy":
            thisAmount = 30000;
            if (perf.getAudience() > 20) {
                thisAmount += 10000 + 500 * (perf.getAudience() - 20);
